  "onl.is.alDugme": ["%1 al · %2 akçe", "Buy %1 · %2 akçe", "Comprar %1 · %2 akçe", "Comprar %1 · %2 akçe", "شراء %1 · %2 أقجة", "Купить %1 · %2 акче"],
