  "onl.is.birimFiyat": ["BİRİM FİYAT", "UNIT PRICE", "PRECIO UNITARIO", "PREÇO UNITÁRIO", "سعر القطعة", "ЦЕНА ЗА ШТ."],
  "onl.is.odendi": ["%1 akçe ödendi", "Paid %1 akçe", "Pagado: %1 akçe", "Pago: %1 akçe", "دُفع %1 أقجة", "Уплачено: %1 акче"],
  "onl.is.kalanPara": ["Kalan: %1 akçe", "Left: %1 akçe", "Quedan: %1 akçe", "Restam: %1 akçe", "المتبقي: %1 أقجة", "Осталось: %1 акче"],
  "onl.is.npcNot": ["NPC'ye ödenen akçe dünyadan çıkar; bir oyuncudan almak hem ucuzdur hem ona kazanç olur.", "Akçe paid to NPCs leaves the world; buying from a player is cheaper and gives them a living.", "El akçe pagado a PNJ sale del mundo; comprar a un jugador es más barato y le da sustento.", "O akçe pago a PNJ sai do mundo; comprar a um jogador é mais barato e dá-lhe sustento.", "الأقجة المدفوعة للأهالي تخرج من العالم، والشراء من لاعب أرخص ويمنحه رزقًا.", "Акче, уплаченные NPC, уходят из мира; купить у игрока дешевле, и это ему заработок."],
  "onl.is.h.verim": ["Bu işten şimdilik verim kalmadı; birkaç ay başka iş yap. Takatin harcanmadı.", "This job yields nothing for now; do other work for a few months. No stamina was spent.", "Este trabajo ya no rinde por ahora; haz otra cosa unos meses. No se gastó energía.", "Este trabalho já não rende por agora; faz outra coisa uns meses. Não se gastou energia.", "لم يبق مردود من هذا العمل حاليًا؛ عمل آخر لبضعة أشهر أفضل. لم تُستهلك الطاقة.", "Сейчас это дело ничего не даёт; лучше несколько месяцев заняться другим. Силы не потрачены."],
  "onl.is.h.takat": ["Takatin bitti; yeni ay dönümünde yenilenir.", "You're out of stamina; it refills at the next month turn.", "Te quedaste sin energía; se repone con el nuevo mes.", "Ficaste sem energia; repõe-se com o novo mês.", "نفدت الطاقة، وتتجدّد مع بداية الشهر التالي.", "Силы кончились; они восстановятся с новым месяцем."],
  "onl.is.h.yas": ["Temel işler %1 yaşında açılır; o güne dek mahallede öğrenmeye devam et.", "Basic work opens at %1; until then keep learning in the quarter.", "El trabajo básico se abre a los %1; hasta entonces sigue aprendiendo en el barrio.", "O trabalho básico abre aos %1; até lá continua a aprender no bairro.", "تُفتح الأعمال الأساسية في سن %1، وحتى ذلك الحين يستمر التعلّم في الحيّ.", "Простая работа открывается в %1 лет; до тех пор продолжай учиться в квартале."],
  "onl.is.h.kota": ["Bu ay bu maldan alınabilecek %1 adedin hepsi alındı; yeni ayı bekle.", "All %1 units of this good allowed this month are bought; wait for the new month.", "Ya se compraron las %1 unidades permitidas este mes; espera al nuevo mes.", "Já se compraram as %1 unidades permitidas este mês; espera pelo novo mês.", "تمّ شراء الحدّ المسموح (%1) من هذه البضاعة هذا الشهر؛ الشهر التالي يجدّده.", "Все %1 шт. этого товара на месяц уже куплены; жди нового месяца."],
  "onl.is.h.para": ["Bu alım için yeterli akçen yok.", "You don't have enough akçe for this purchase.", "No tienes suficientes akçe para esta compra.", "Não tens akçe suficientes para esta compra.", "لا تكفي الأقجة لهذا الشراء.", "Не хватает акче на эту покупку."],
